194	        create("req-m12", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
195	        // 候选读数 1.00 与基线 1.0 数值相等：视为未改，保留当前；结果与当前相同，不加版本
196	        merge("req-m13", "obs-1", 1, "站点A", "1.00", "备注")
