1:package com.example.starter.observation;
3:import org.springframework.http.HttpStatus;
4:import org.springframework.http.ResponseEntity;
5:import org.springframework.validation.FieldError;
6:import org.springframework.web.bind.MethodArgumentNotValidException;
7:import org.springframework.web.bind.annotation.ExceptionHandler;
8:import org.springframework.web.bind.annotation.RestControllerAdvice;
10:import java.util.stream.Collectors;
12:/**
13: * 全局异常处理：业务异常与参数校验失败统一转为 ErrorResponse。
14: */
15:@RestControllerAdvice
16:public class ApiExceptionHandler {
18:    /**
19:     * 业务异常：404/409/410 等，携带冲突字段与当前版本（如有）。
20:     */
21:    @ExceptionHandler(ApiException.class)
22:    public ResponseEntity<ErrorResponse> handleApiException(ApiException ex) {
23:        HttpStatus status = ex.status();
24:        ErrorResponse body = new ErrorResponse(status.value(), status.getReasonPhrase(),
25:                ex.getMessage(), ex.conflictFields(), ex.currentVersion());
26:        return ResponseEntity.status(status).body(body);
27:    }
29:    /**
30:     * 请求体校验失败：400，汇总字段错误信息。
31:     */
32:    @ExceptionHandler(MethodArgumentNotValidException.class)
33:    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
34:        String message = ex.getBindingResult().getFieldErrors().stream()
35:                .map(ApiExceptionHandler::formatFieldError)
36:                .collect(Collectors.joining("; "));
37:        ErrorResponse body = new ErrorResponse(HttpStatus.BAD_REQUEST.value(),
38:                HttpStatus.BAD_REQUEST.getReasonPhrase(), message, null, null);
39:        return ResponseEntity.badRequest().body(body);
40:    }
42:    private static String formatFieldError(FieldError error) {
43:        return error.getField() + ": "
44:                + (error.getDefaultMessage() == null ? "invalid" : error.getDefaultMessage());
45:    }
46:}

