 */
public enum QualityCategory {
    /** 传感器异常 */
    SENSOR_FAULT,
    /** 人工误操作 */
    HUMAN_ERROR,
    /** 环境干扰 */
    ENVIRONMENT_INTERFERENCE
}

package com.example.starter.observation;

/**
 * 复核结论：CONFIRMED 确认（扣减置信度）/ DISMISSED 驳回（不影响置信度）。
 */
public enum ReviewConclusion {
    /** 确认质量问题成立 */
    CONFIRMED,
    /** 驳回质量问题 */
    DISMISSED
}

package com.example.starter.observation;

/**
 * 质量标记状态。
 */
public enum FlagStatus {
    /** 待复核 */
    PENDING_REVIEW,
    /** 已确认（复核结论 CONFIRMED） */
    CONFIRMED,
    /** 已驳回（复核结论 DISMISSED） */
    DISMISSED,
    /** 已过期：观测产生新版本，不再可复核，也不影响新版本 */
    STALE
}

